confirmed.replay:
set -u; ST="$SANDBOX/st"; printf 'version: "1.0"
name: r
machines: { local: { hostname: localhost, addr: 127.0.0.1 } }
resources:
  f: { type: file, machine: local, path: "%s/o.txt", content: "x" }
' "$SANDBOX" > c.yaml; "$FORJAR" apply -f c.yaml --state-dir "$ST" --yes >/dev/null 2>&1; "$FORJAR" drift -f c.yaml --state-dir "$ST" --tripwire -m nosuchmachine >/dev/null 2>&1 && { echo "DEFECT: unknown machine reported clean"; exit 1; }; "$FORJAR" drift -f c.yaml --state-dir "$ST" --tripwire -m local >/dev/null 2>&1 || { echo "DEFECT: known machine now fails"; exit 1; }; exit 0

set -u; ST="$SANDBOX/st"; printf 'version: "1.0"
name: r
machines: { local: { hostname: localhost, addr: 127.0.0.1 } }
resources:
  f: { type: file, machine: local, path: "%s/o.txt", content: "orig" }
' "$SANDBOX" > c.yaml; "$FORJAR" apply -f c.yaml --state-dir "$ST" --yes >/dev/null 2>&1; "$FORJAR" status --state-dir "$ST" -f c.yaml --hash-verify >/dev/null 2>&1 || { echo "DEFECT: clean stack failed hash-verify"; exit 1; }; echo TAMPERED > "$SANDBOX/o.txt"; "$FORJAR" status --state-dir "$ST" -f c.yaml --hash-verify >/dev/null 2>&1 && { echo "DEFECT: tampered file passed"; exit 1; }; exit 0

set -u; ST="$SANDBOX/st"; printf 'version: "1.0"
name: r
machines: { local: { hostname: localhost, addr: 127.0.0.1 } }
resources:
  a: { type: file, machine: local, path: "%s/a.txt", content: "A" }
  b: { type: file, machine: local, path: "%s/b.txt", content: "B" }
' "$SANDBOX" "$SANDBOX" > forjar.yaml; "$FORJAR" apply -f forjar.yaml --state-dir "$ST" --yes >/dev/null 2>&1; sed -i "/^  b:/d" forjar.yaml; "$FORJAR" lock-prune --state-dir "$ST" --yes >/dev/null 2>&1; n=$(grep -cE "^  [ab]:" "$ST/local/state.lock.yaml"); [ "$n" = "1" ] || { echo "DEFECT: prune left $n entries"; exit 1; }; exit 0

set -u; printf 'version: "1.0"
name: alpha
policy: { failure: stop_on_first }
machines: { local: { hostname: l, addr: 127.0.0.1 } }
resources: {}
' > a.yaml; sed "s/alpha/BRAVO/; s/stop_on_first/continue_independent/" a.yaml > b.yaml; OUT=$("$FORJAR" stack-diff a.yaml b.yaml 2>&1); echo "$OUT" | grep -q "No differences found" && { echo "DEFECT: name+policy differences missed"; exit 1; }; OUT2=$("$FORJAR" stack-diff a.yaml a.yaml 2>&1); echo "$OUT2" | grep -q "No differences found" || { echo "DEFECT: identical configs reported different"; exit 1; }; exit 0

set -u; printf 'version: "1.0"
name: r
machines: { local: { hostname: l, addr: 127.0.0.1 } }
resources:
  x: { type: file, machine: NOSUCH, path: /tmp/z, content: "a" }
' > bad.yaml; OUT=$("$FORJAR" validate -f bad.yaml --json 2>/dev/null); [ -n "$OUT" ] || { echo "DEFECT: zero json on failure"; exit 1; }; printf "%s" "$OUT" | python3 -c "import sys,json; d=json.load(sys.stdin); raise SystemExit(0 if d.get("valid") is False else 1)" || { echo "DEFECT: not valid json or wrong flag"; exit 1; }; exit 0

